mapper.sql:
tenant_id = #{claim.job.tenantId} AND owner_id = #{claim.job.ownerId}
        AND job_id = #{claim.job.jobId} AND document_version = #{claim.job.documentVersion}
        AND index_generation = #{claim.job.indexGeneration}
        AND lease_owner = #{claim.worker} AND lease_epoch = #{claim.epoch}
        AND status = 'PROCESSING' AND lease_until > UTC_TIMESTAMP(6)

mapper.update:
UPDATE knowledge_ingestion SET extraction_key = #{ref.key}, extraction_hash = #{ref.hash},
    extraction_bytes = #{ref.sizeBytes}, extraction_digest = #{ref.extractionDigest},
    extraction_warnings = CAST(#{warnings} AS JSON), revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE  AND extraction_key IS NULL AND prepared_key IS NULL
    AND preparation_schema = #{claim.job.preparationSchema} AND processor_version = #{claim.job.profile.processor}
    AND parser_profile = #{claim.job.profile.parser}

UPDATE knowledge_ingestion SET
vector_state = 'DONE', keyword_state = 'DONE',
revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE AND prepared_key IS NOT NULL AND batch_digest = #{claim.prepared.batchDigest}

UPDATE knowledge_document SET status = #{state},
    updated_at = UTC_TIMESTAMP(6)
WHERE tenant_id = #{caller.tenantId} AND owner_id = #{caller.userId} AND document_id = #{id}
    AND version = #{version} AND ingestion_job_id = #{jobId} AND active_job_id = #{jobId}
    AND lifecycle = 'ACTIVE' AND lifecycle_ready = TRUE

UPDATE knowledge_document d JOIN knowledge_ingestion j ON j.tenant_id = d.tenant_id
    AND j.owner_id = d.owner_id AND j.document_id = d.document_id AND j.job_id = #{claim.job.jobId}
SET d.published_version = j.document_version, d.published_generation = j.index_generation,
    d.published_job_id = j.job_id, d.revision = d.revision + 1, d.updated_at = UTC_TIMESTAMP(6),
    d.status = CASE WHEN d.ingestion_job_id = j.job_id THEN 'READY' ELSE d.status END
WHERE d.tenant_id = #{claim.job.tenantId} AND d.owner_id = #{claim.job.ownerId} AND d.document_id = #{claim.job.documentId}
    AND d.lifecycle_ready = TRUE AND d.lifecycle = 'ACTIVE' AND d.active_job_id = j.job_id AND d.revision < 2147483647
    AND d.published_version <=> j.base_published_version
    AND d.published_generation <=> j.base_published_generation
    AND d.published_job_id <=> j.base_published_job_id
    AND j.status = 'PROCESSING' AND j.lease_owner = #{claim.worker} AND j.lease_epoch = #{claim.epoch}
    AND j.lease_until > UTC_TIMESTAMP(6) AND j.vector_state = 'DONE' AND j.keyword_state = 'DONE'
    AND j.document_version = #{claim.job.documentVersion} AND j.index_generation = #{claim.job.indexGeneration}
    AND (j.command_scope = 'REINDEX' OR (d.version = j.document_version AND d.ingestion_job_id = j.job_id))
    AND j.batch_digest = #{claim.prepared.batchDigest}
